import React, { useRef } from 'react';
import TableContainer from '@material-ui/core/TableContainer';
import { useChainWheel } from 'utils/useContainWheel';

// A table that scrolls inside its own box: the wheel over it scrolls the rows first (the page has its own wheel script that would
// otherwise take it), and once the rows are at the top or the end the same wheel scrolls the page on, so nobody has to move the
// mouse off the table.
const ScrollTable = ({ maxHeight, children }) => {
  const ref = useRef(null);
  useChainWheel(ref);
  return (
    <TableContainer ref={ref} style={{ maxHeight }}>
      {children}
    </TableContainer>
  );
};

export default ScrollTable;
