import React, { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import { useHistory, useLocation } from 'react-router-dom';
import { Row, Col } from 'reactstrap';
import CustomSelect from 'components/CustomSelect';
import constants from 'config/constants';
import { store } from 'index';
import { showToast } from 'actions/admin/auth';
import { fetchPromotionBatchesApi } from 'actions/admin/promotion';
import { fetchCarryForwardRunsApi, rollbackCarryForwardRunApi } from 'actions/admin/carryForward';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import { decodeUrlId, encodeUrlId } from 'utils/urlIdCodec';
import { CARRY_STEPS, appliedRunOf, stepLabel, suggestSourceBatch, suggestTargetBatch } from 'utils/carryForward';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import EmptyState from 'views/admin/Common/EmptyState';
import { ReportPaper } from 'views/admin/Common/ReportBits';
import CarryStepCard from './components/CarryStepCard';
import CarryHistory from './components/CarryHistory';

// One page per kind (each has its own sidebar item under "New academic year").
const KINDS = {
  transport: {
    title: 'Transport carry forward',
    intro:
      'Bring the bus routes and the students who use them from the previous batch into the new one. Routes first, then students.',
    nothing: 'Ask an admin to copy the transport into the new batch.',
  },
  fees: {
    title: 'Fees carry forward',
    intro:
      'Bring the fee structures, the fee group of each class and the fees of single students into the new batch. Fee structures first.',
    nothing: 'Ask an admin to copy the fees into the new batch.',
  },
};

const toastError = err => store.dispatch(showToast(formResMessage(err), 'error'));
const toast = (message, type = 'success') => store.dispatch(showToast(message, type));

// After the year-end promotion the new batch has no transport or fees yet. This page copies them over from the previous batch:
// pick the two batches, preview each step, copy, and roll a run back if it was a mistake. The same steps and safety as the
// student promotion (nothing is changed until you copy, copying twice never duplicates, every run can be rolled back).
const CarryForwardWizard = ({ kind }) => {
  const history = useHistory();
  const location = useLocation();
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;

  const firstQuery = useRef(new URLSearchParams(location.search));
  const [sourceBatchId, setSourceBatchId] = useState(() => decodeUrlId(firstQuery.current.get('from')));
  const [targetBatchId, setTargetBatchId] = useState(() => decodeUrlId(firstQuery.current.get('to')));
  const [batches, setBatches] = useState([]);
  const [batchesLoading, setBatchesLoading] = useState(false);

  const [runs, setRuns] = useState([]);
  const [runsLoading, setRunsLoading] = useState(false);
  const [rollingBackId, setRollingBackId] = useState(0);
  const [reloadKey, setReloadKey] = useState(0);
  const [confirm, setConfirm] = useState(null);

  const { title, intro } = KINDS[kind];
  const sameBatch = !!sourceBatchId && sourceBatchId === targetBatchId;
  const ready = !!sourceBatchId && !!targetBatchId && !sameBatch;
  const ids = { token, schoolId, sourceBatchId, targetBatchId };
  const batchName = id => batches.find(el => el.batchId === id)?.name || `Batch ${id}`;
  const askConfirm = (message, onYes) => setConfirm({ message, onYes });

  // the address carries both batches, so a reload (or a shared link) lands in the same place
  useEffect(() => {
    const params = new URLSearchParams();
    if (sourceBatchId) params.set('from', encodeUrlId(sourceBatchId));
    if (targetBatchId) params.set('to', encodeUrlId(targetBatchId));
    history.replace(`${location.pathname}?${params.toString()}`);
  }, [sourceBatchId, targetBatchId]);

  // the new batch is the newest one, and the batch to copy from the one before it, unless the address already chose
  useEffect(() => {
    if (!schoolId) return;
    setBatchesLoading(true);
    fetchPromotionBatchesApi({ token, schoolId })
      .then(list => {
        setBatches(list || []);
        const target = targetBatchId || suggestTargetBatch(list);
        setTargetBatchId(target);
        if (!sourceBatchId) setSourceBatchId(suggestSourceBatch(list, target));
      })
      .catch(toastError)
      .finally(() => setBatchesLoading(false));
  }, []);

  const loadRuns = () => {
    if (!schoolId || !targetBatchId) {
      setRuns([]);
      return Promise.resolve();
    }
    setRunsLoading(true);
    return fetchCarryForwardRunsApi({ kind, token, schoolId, targetBatchId })
      .then(list => setRuns([...list].sort((a, b) => b.runId - a.runId)))
      .catch(toastError)
      .finally(() => setRunsLoading(false));
  };
  useEffect(() => {
    loadRuns();
  }, [kind, targetBatchId]);

  const onDone = (step, data) => {
    toast(`${step.title}: ${data.created} copied${step.select ? `, ${data.skipped ?? 0} skipped` : ''}`);
    loadRuns();
    setReloadKey(key => key + 1);
  };

  const onRollback = run => {
    askConfirm(
      `Roll back run #${run.runId} (${stepLabel(run.step)})? This deletes the ${
        run.createdCount
      } record(s) that run created in ${batchName(targetBatchId)}.`,
      async () => {
        setRollingBackId(run.runId);
        try {
          await rollbackCarryForwardRunApi({ kind, token, runId: run.runId });
          toast(`Run #${run.runId} rolled back`);
          await loadRuns();
          setReloadKey(key => key + 1);
        } catch (err) {
          toastError(err);
        } finally {
          setRollingBackId(0);
        }
      }
    );
  };

  if (!schoolId) {
    return (
      <div className="content">
        <EmptyState
          icon="fas fa-school"
          title="Select a school first"
          subtitle="Carry forward works on one school at a time."
        />
      </div>
    );
  }

  const batchOptions = batches.map(el => ({ ...el, label: el.name, value: el.batchId }));

  return (
    <div className="content">
      <ReportPaper title={title} intro={intro}>
        <div
          style={{
            background: '#faf7fc',
            borderRadius: 6,
            padding: '10px 14px',
            margin: '8px 0 16px',
            fontSize: 13,
            color: '#2b3a4a',
          }}>
          <b>How it works</b>
          <ol style={{ margin: '6px 0 0', paddingLeft: 18 }}>
            <li>Choose the old year to copy from and the new year to copy into (do the Student promotion first).</li>
            <li>For each step below, press &ldquo;Show what will be copied&rdquo; and check the list.</li>
            <li>Press a Copy button. Nothing is changed before that, and copying twice never makes duplicates.</li>
            <li>Made a mistake? Roll the step back in &ldquo;History &amp; rollback&rdquo; at the bottom.</li>
          </ol>
        </div>
        <Row>
          <Col md={4}>
            <CustomSelect
              label="Copy from (old year)"
              name="sourceBatchId"
              value={sourceBatchId}
              loading={batchesLoading}
              usePortal
              error={sameBatch}
              onChange={(name, value) => setSourceBatchId(value)}
              options={batchOptions}
            />
          </Col>
          <Col md={4}>
            <CustomSelect
              label="Copy into (new year)"
              name="targetBatchId"
              value={targetBatchId}
              loading={batchesLoading}
              usePortal
              error={sameBatch}
              onChange={(name, value) => setTargetBatchId(value)}
              options={batchOptions}
            />
          </Col>
        </Row>
        {sameBatch && (
          <div style={{ color: '#c62828', fontSize: 13, marginTop: 10 }}>
            Both boxes show the same year. Choose a different old year and new year.
          </div>
        )}
      </ReportPaper>

      {!ready && <ReportPaper title="Choose the two years to start" />}

      {/* a new batch pair starts with fresh previews */}
      {CARRY_STEPS[kind].map((step, index) => (
        <CarryStepCard
          key={`${kind}-${step.key}-${sourceBatchId}-${targetBatchId}`}
          kind={kind}
          step={step}
          number={index + 1}
          ids={ids}
          disabled={!ready}
          appliedRun={appliedRunOf(step, runs)}
          reloadKey={reloadKey}
          askConfirm={askConfirm}
          onDone={onDone}
          onError={toastError}
        />
      ))}

      {!!targetBatchId && (
        <CarryHistory
          kind={kind}
          runs={runs}
          loading={runsLoading}
          rollingBackId={rollingBackId}
          onReload={loadRuns}
          onRollback={onRollback}
        />
      )}

      <ConfirmModal
        size="md"
        confirmModalOpen={!!confirm}
        confirmMessage={confirm?.message}
        deleteConfirm={() => {
          const onYes = confirm?.onYes;
          setConfirm(null);
          if (onYes) onYes();
        }}
        deleteCancel={() => setConfirm(null)}
      />
    </div>
  );
};

// Carrying a whole school forward is for the admins (school admin and super admin), not for teachers.
const CarryForwardPage = ({ kind = 'transport' }) => {
  const loggedUserRole = useSelector(state => state.auth.loggedUserRole);
  if (![constants.roles.admin, constants.roles.SA].includes(loggedUserRole)) {
    return (
      <div className="content">
        <EmptyState icon="fas fa-lock" title="Only an admin can carry forward" subtitle={KINDS[kind].nothing} />
      </div>
    );
  }
  return <CarryForwardWizard kind={kind} />;
};

export default CarryForwardPage;
