// Pure helpers of the carry-forward page (views/admin/CarryForward): transport and fee set-up copied into a new batch.

export const ELIGIBLE = 'ELIGIBLE';
export const RUN_APPLIED = 'APPLIED';
export const RUN_ROLLED_BACK = 'ROLLED_BACK';

// What each kind copies, step by step. `path` is the part of the URL after .../carry-forward/, `select` is the field of a
// preview row that is sent back when only some rows are ticked (a step with no `select` copies everything in one go).
