// The applied run that already copied a step that has no per-row choice (routes, fee structures). The backend refuses to copy
// those twice, so the page says so and holds the button until that run is rolled back.
export const appliedRunOf = (step, runs) =>
  step.runStep ? (runs || []).find(run => run.status === RUN_APPLIED && run.step === step.runStep) : undefined;

// A step's preview rows are selectable only while they can still be copied.
export const isEligible = row => row?.status === ELIGIBLE;

// How many preview rows are in each status, e.g. { ELIGIBLE: 12, SKIPPED_ALREADY_HAS_TRANSPORT: 6 }.
export const statusCounts = rows =>
  (rows || []).reduce((counts, row) => {
    const key = row.status || 'UNKNOWN';
    return { ...counts, [key]: (counts[key] || 0) + 1 };
  }, {});

export const eligibleCount = rows => (rows || []).filter(isEligible).length;

// The id of every eligible row, for the "tick all" box and as the default selection of a fresh preview.
export const eligibleIds = (rows, select) => (rows || []).filter(isEligible).map(row => row[select]);

export const sumOf = (rows, field) => (rows || []).reduce((total, row) => total + (Number(row[field]) || 0), 0);

// "SKIPPED_NOT_IN_TARGET_BATCH" -> "Not in target batch" when the backend sent no label of its own.
export const statusText = row => {
  if (row?.statusLabel) return row.statusLabel;
  const raw = String(row?.status || '')
    .replace(/^SKIPPED_/, '')
    .replace(/_/g, ' ')
    .toLowerCase();
  return raw.charAt(0).toUpperCase() + raw.slice(1);
};

export const statusTone = row => (isEligible(row) ? 'good' : 'warn');

// Rollback has an order: students (and class fees) before the routes / fee structures they depend on. The backend enforces
// it too; this only decides which button to offer. `runs` is the history of the target batch.
const FIRST_TO_UNDO = { transport: ['STUDENTS'], fees: ['STUDENT_FEES', 'COURSE_FEES'] };
const LAST_TO_UNDO = { transport: ['ROUTES'], fees: ['FEE_STRUCTURES'] };

export const rollbackBlockedBy = (kind, run, runs) => {
  if (run.status !== RUN_APPLIED || !LAST_TO_UNDO[kind].includes(run.step)) return null;
  const blocker = (runs || []).find(
    other => other.status === RUN_APPLIED && FIRST_TO_UNDO[kind].includes(other.step) && other.runId > run.runId
  );
  return blocker ? `Roll back run #${blocker.runId} (${stepLabel(blocker.step)}) first` : null;
};

const STEP_LABELS = {
  ROUTES: 'Routes',
  STUDENTS: 'Students',
  FEE_STRUCTURES: 'Fee structures',
  COURSE_FEES: 'Class fees',
  STUDENT_FEES: 'Student fees',
};
export const stepLabel = step => STEP_LABELS[step] || step || '--';

// The batch to copy from when a target is picked: the batch that starts the year before it.
export const suggestSourceBatch = (batches, targetBatchId) => {
  const target = (batches || []).find(el => el.batchId === targetBatchId);
  if (!target) return 0;
  const before = (batches || [])
    .filter(el => el.batchId !== target.batchId && Number(el.startYear) < Number(target.startYear))
    .sort((a, b) => Number(b.startYear) - Number(a.startYear))[0];
  return before?.batchId || 0;
};

// The newest batch is normally the one being set up, so that is the default target.
export const suggestTargetBatch = batches =>
  [...(batches || [])].sort((a, b) => Number(b.startYear) - Number(a.startYear) || b.batchId - a.batchId)[0]?.batchId ||
  0;
