// Lightweight, reversible obfuscation for numeric ids shown in the browser's URL bar.
//
// This is NOT real security - the code and the value both live entirely in the
// client bundle, so anyone can pull this file out of devtools and decode any id.
// It only keeps raw sequential database ids (courseId=29) from being visible at a
// glance in a shared URL or screenshot. All actual API calls still use the plain
// numeric id - the backend never sees or needs the encoded form.
export const encodeUrlId = id => (id ? btoa(String(id)) : '');

export const decodeUrlId = encoded => {
  if (!encoded) return 0;
  try {
    const decoded = Number(atob(encoded));
    return Number.isFinite(decoded) ? decoded : 0;
  } catch {
    return 0;
  }
};
