import React, { useEffect, useMemo, useState } from 'react';
import { Checkbox } from '@material-ui/core';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import CustomButton from 'components/CustomButton';
import { Chip } from 'views/admin/Promotion/components/StatusChip';
import ScrollTable from 'views/admin/Promotion/components/ScrollTable';
import { HeadCell } from 'views/admin/Common/ReportBits';
import Paper from '@material-ui/core/Paper';
import colors from 'config/colors';
import StatTile from 'views/admin/Common/StatTile';
import { SkeletonRows } from 'views/admin/Common/Loader';
import { applyCarryForwardApi, previewCarryForwardApi } from 'actions/admin/carryForward';
import {
  eligibleCount,
  eligibleIds,
  isEligible,
  statusCounts,
  statusText,
  statusTone,
  sumOf,
} from 'utils/carryForward';
import { CARRY_COLUMNS, CARRY_TOTALS } from '../columns';

const NUMBER_BADGE = {
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: 22,
  height: 22,
  borderRadius: 11,
  background: colors.accent,
  color: '#fff',
  fontSize: 12,
  fontWeight: 'bold',
  marginRight: 8,
  flexShrink: 0,
};

// One step of a carry forward: look at what would be copied (preview), then copy it. A step that has a `select` field lets the
// admin tick the rows to copy (all the eligible ones are ticked to begin with); the others copy everything in one go.
// `reloadKey` changes when anything was applied or rolled back, so a preview that is open shows the new statuses.
const CarryStepCard = ({ kind, step, number, ids, disabled, appliedRun, reloadKey, askConfirm, onDone, onError }) => {
  const columns = CARRY_COLUMNS[`${kind}.${step.key}`];
  const total = CARRY_TOTALS[`${kind}.${step.key}`];
  const [rows, setRows] = useState(null);
  const [loading, setLoading] = useState(false);
  const [applying, setApplying] = useState(false);
  const [selected, setSelected] = useState(() => new Set());
  const [result, setResult] = useState(null);

  const call = { kind, path: step.path, ...ids };
  const hasStatus = !!step.select;

  const preview = async () => {
    setLoading(true);
    try {
      const list = await previewCarryForwardApi(call);
      setRows(list);
      setSelected(new Set(eligibleIds(list, step.select)));
    } catch (err) {
      onError(err);
    } finally {
      setLoading(false);
    }
  };

  // a new batch pair (or a finished run elsewhere on the page) makes an earlier preview stale: refresh it if one was open
  useEffect(() => {
    if (rows) preview();
  }, [reloadKey]);

  const counts = useMemo(() => statusCounts(rows), [rows]);
  const eligible = hasStatus ? eligibleCount(rows) : (rows || []).length;
  const tickedCount = selected.size;

  const apply = async postData => {
    setApplying(true);
    try {
      const data = await applyCarryForwardApi({ ...call, postData });
      setResult(data);
      onDone(step, data);
    } catch (err) {
      onError(err);
    } finally {
      setApplying(false);
    }
  };

  const toggle = id =>
    setSelected(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  const allTicked = eligible > 0 && tickedCount === eligible;

  return (
    <Paper square style={{ padding: 16, marginBottom: 16 }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <span style={NUMBER_BADGE}>{number}</span>
          <b style={{ color: colors.accentDark }}>{step.title}</b>
        </div>
        {step.runStep && (
          <Chip
            label={appliedRun ? `Copied (run #${appliedRun.runId})` : 'Not copied yet'}
            tone={appliedRun ? 'good' : 'neutral'}
          />
        )}
      </div>
      <div style={{ fontSize: 12, color: '#7d7d7d', margin: '2px 0 12px 30px' }}>{step.intro}</div>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 12 }}>
        <CustomButton
          variant="outlined"
          name={rows ? 'Refresh the list' : 'Show what will be copied'}
          showLoader
          loading={loading}
          disabled={disabled || loading || applying}
          onClick={preview}
        />
        {hasStatus ? (
          <>
            <CustomButton
              name={`Copy all ready${rows ? ` (${eligible})` : ''}`}
              showLoader
              loading={applying}
              disabled={disabled || applying || !rows || eligible === 0}
              onClick={() =>
                askConfirm(`Copy all ${eligible} eligible row(s) into the new batch?`, () => apply(undefined))
              }
            />
            <CustomButton
              variant="outlined"
              name={`Copy only ticked${rows ? ` (${tickedCount})` : ''}`}
              disabled={disabled || applying || !rows || tickedCount === 0}
              onClick={() =>
                askConfirm(`Copy the ${tickedCount} ticked row(s) into the new batch?`, () => apply([...selected]))
              }
            />
          </>
        ) : (
          <CustomButton
            name="Copy now"
            showLoader
            loading={applying}
            disabled={disabled || applying || !rows || rows.length === 0 || !!appliedRun}
            onClick={() =>
              askConfirm(`${step.title} into the new batch? You can roll it back from the history below.`, () =>
                apply(undefined)
              )
            }
          />
        )}
      </div>

      {!rows && !disabled && (
        <div style={{ fontSize: 12, color: '#7d7d7d', marginBottom: 8 }}>
          Press &ldquo;Show what will be copied&rdquo; first. Nothing is changed until you press a Copy button.
        </div>
      )}

      {!!appliedRun && !hasStatus && (
        <div style={{ color: '#b26a00', fontSize: 13, marginBottom: 10 }}>
          Already copied in run #{appliedRun.runId}. Roll that run back in the history below to copy again.
        </div>
      )}

      {result && (
        <div style={{ color: '#2e7d32', fontSize: 13, fontWeight: 'bold', marginBottom: 10 }}>
          Done. Run #{result.runId} created {result.created}
          {hasStatus ? `, skipped ${result.skipped ?? 0}` : ''}.
        </div>
      )}

      {loading && !rows && <SkeletonRows rows={4} avatar={false} />}

      {rows && (
        <>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 12 }}>
            <StatTile label="In previous batch" value={rows.length} />
            {hasStatus && <StatTile label="Eligible" value={eligible} tone="good" />}
            {hasStatus && rows.length - eligible > 0 && (
              <StatTile label="Skipped" value={rows.length - eligible} tone="warn" />
            )}
            {total && <StatTile label={total.label} value={sumOf(rows, total.field).toLocaleString('en-IN')} />}
          </div>

          {rows.length === 0 ? (
            <div style={{ color: '#6b778a', padding: '12px 0' }}>{step.empty}</div>
          ) : (
            <ScrollTable maxHeight={420}>
              <Table size="small" stickyHeader>
                <TableHead>
                  <TableRow>
                    {hasStatus && (
                      <TableCell padding="checkbox">
                        <Checkbox
                          size="small"
                          color="primary"
                          checked={allTicked}
                          indeterminate={tickedCount > 0 && !allTicked}
                          disabled={eligible === 0}
                          onChange={e => setSelected(new Set(e.target.checked ? eligibleIds(rows, step.select) : []))}
                        />
                      </TableCell>
                    )}
                    {columns.map(col => (
                      <TableCell key={col.label} align={col.align}>
                        {col.label}
                      </TableCell>
                    ))}
                    {hasStatus && <HeadCell>Status</HeadCell>}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {rows.map((row, index) => (
                    <TableRow key={row[step.select] ?? row.feeStructId ?? index} hover>
                      {hasStatus && (
                        <TableCell padding="checkbox">
                          <Checkbox
                            size="small"
                            color="primary"
                            checked={selected.has(row[step.select])}
                            disabled={!isEligible(row)}
                            onChange={() => toggle(row[step.select])}
                          />
                        </TableCell>
                      )}
                      {columns.map(col => (
                        <TableCell key={col.label} align={col.align}>
                          {col.render(row)}
                        </TableCell>
                      ))}
                      {hasStatus && (
                        <TableCell>
                          <Chip label={statusText(row)} tone={statusTone(row)} />
                          {row.statusMessage && !isEligible(row) && (
                            <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2, maxWidth: 420 }}>
                              {row.statusMessage}
                            </div>
                          )}
                        </TableCell>
                      )}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </ScrollTable>
          )}
          {hasStatus && Object.keys(counts).length > 1 && (
            <div style={{ fontSize: 12, color: '#8b95a1', marginTop: 6 }}>
              {Object.keys(counts)
                .map(key => `${key.replace(/_/g, ' ').toLowerCase()}: ${counts[key]}`)
                .join('  |  ')}
            </div>
          )}
        </>
      )}
    </Paper>
  );
};

export default CarryStepCard;
