import React from 'react';
import moment from 'moment';
import { Card } from '@material-ui/core';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import CustomButton from 'components/CustomButton';
import { Chip } from 'views/admin/Promotion/components/StatusChip';
import ScrollTable from 'views/admin/Promotion/components/ScrollTable';
import StepHeader from 'views/admin/Promotion/components/StepHeader';
import { RUN_APPLIED, RUN_ROLLED_BACK, rollbackBlockedBy, stepLabel } from 'utils/carryForward';

const when = value => (value ? moment(value).format('DD MMM YYYY, hh:mm A') : '--');

// Every carry forward done into the target batch, newest first, each with a Rollback while it is still applied. Rolling back
// deletes only what that run created. Students / class fees have to be rolled back before the routes / fee structures.
const CarryHistory = ({ kind, runs, loading, rollingBackId, onReload, onRollback }) => (
  <Card className="p-3 mb-3">
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8 }}>
      <StepHeader
        title="History & rollback"
        intro="Roll back students (and class fees) first, then routes (or fee structures). Rollback is allowed from November to May only."
      />
      <CustomButton variant="outlined" size="small" name="Reload" showLoader loading={loading} onClick={onReload} />
    </div>
    {!runs.length ? (
      <div style={{ color: '#6b778a', padding: '8px 0' }}>
        {loading ? 'Loading...' : 'Nothing copied into this batch yet.'}
      </div>
    ) : (
      <ScrollTable maxHeight={320}>
        <Table size="small" stickyHeader>
          <TableHead>
            <TableRow>
              <TableCell>Run</TableCell>
              <TableCell>Step</TableCell>
              <TableCell>Status</TableCell>
              <TableCell align="right">Created</TableCell>
              <TableCell align="right">Skipped</TableCell>
              <TableCell>By</TableCell>
              <TableCell>At</TableCell>
              <TableCell>Rolled back</TableCell>
              <TableCell />
            </TableRow>
          </TableHead>
          <TableBody>
            {runs.map(run => {
              const blocked = rollbackBlockedBy(kind, run, runs);
              return (
                <TableRow key={run.runId} hover>
                  <TableCell>#{run.runId}</TableCell>
                  <TableCell>{stepLabel(run.step)}</TableCell>
                  <TableCell>
                    <Chip
                      label={
                        run.status === RUN_APPLIED
                          ? 'Applied'
                          : run.status === RUN_ROLLED_BACK
                          ? 'Rolled back'
                          : run.status
                      }
                      tone={run.status === RUN_APPLIED ? 'good' : 'neutral'}
                    />
                  </TableCell>
                  <TableCell align="right">{run.createdCount ?? 0}</TableCell>
                  <TableCell align="right">{run.skippedCount ?? 0}</TableCell>
                  <TableCell>{run.createdBy || '--'}</TableCell>
                  <TableCell style={{ whiteSpace: 'nowrap' }}>{when(run.createdAt)}</TableCell>
                  <TableCell style={{ whiteSpace: 'nowrap' }}>
                    {run.rolledBackAt
                      ? `${when(run.rolledBackAt)}${run.rolledBackBy ? ` by ${run.rolledBackBy}` : ''}`
                      : '--'}
                  </TableCell>
                  <TableCell align="right">
                    {run.status === RUN_APPLIED && (
                      <span title={blocked || ''}>
                        <CustomButton
                          size="small"
                          variant="outlined"
                          name="Rollback"
                          showLoader
                          loading={rollingBackId === run.runId}
                          disabled={!!blocked || !!rollingBackId}
                          onClick={() => onRollback(run)}
                        />
                      </span>
                    )}
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </ScrollTable>
    )}
  </Card>
);

export default CarryHistory;
