import axios from 'axios';
import constants from '../../config/constants';

// Carry forward: copy what a school set up for the previous academic year (transport routes and students, fee structures
// and the fees of classes and students) into the new batch. Two families of calls with the same shape, each under its own
// path, and both are safe to repeat: students that already have the record are skipped, and every apply is a "run" that can
// be rolled back (students / class fees first, then routes / fee structures).
//   /api/transport/carry-forward/...   step 1 routes, step 2 students
//   /api/termfee/carry-forward/...     step 1 fee structures, step 2 classes, step 3 student fees
export const CARRY_KINDS = {
  transport: `${constants.API_BASE_URL}/api/transport/carry-forward`,
  fees: `${constants.API_BASE_URL}/api/termfee/carry-forward`,
};

const scope = ({ schoolId, sourceBatchId, targetBatchId }) => ({ schoolId, sourceBatchId, targetBatchId });

export const previewCarryForwardApi = ({ kind, path, token, ...ids }) =>
  axios
    .get(`${CARRY_KINDS[kind]}/${path}/preview${constants.makeParams(scope(ids))}`, constants.setHeader(token))
    .then(res => res.data || []);

// postData: the ids ticked on the preview, or nothing to copy everything that is eligible. Routes / fee structures take no ids.
export const applyCarryForwardApi = ({ kind, path, token, postData, ...ids }) =>
  axios
    .post(`${CARRY_KINDS[kind]}/${path}/apply${constants.makeParams(scope(ids))}`, postData, constants.setHeader(token))
    .then(res => res.data);

export const fetchCarryForwardRunsApi = ({ kind, token, schoolId, targetBatchId }) =>
  axios
    .get(`${CARRY_KINDS[kind]}/runs${constants.makeParams({ schoolId, targetBatchId })}`, constants.setHeader(token))
    .then(res => res.data || []);

export const rollbackCarryForwardRunApi = ({ kind, token, runId }) =>
  axios.post(`${CARRY_KINDS[kind]}/runs/${runId}/rollback`, undefined, constants.setHeader(token));
