// Pure helpers of the student promotion page (views/admin/Promotion).

export const FINAL_CLASS = 'FINAL';

// LEGACY: a request made by the old rollover (clone batch) - it has no plan and cannot be opened here.
export const RUN_STATUS = { created: 'BATCH_CREATED', planReady: 'PLAN_READY', promoted: 'PROMOTED', legacy: 'LEGACY' };

export const PLAN_ACTIONS = ['PROMOTE', 'GRADUATE', 'EXCLUDE'];

export const PLAN_ACTION_LABELS = { PROMOTE: 'Promote', GRADUATE: 'Graduate', EXCLUDE: 'Exclude' };

// The wizard step a request is at: 0 class order, 1 new batch, 2 review plan, 3 promote. A request exists from step 1 on.
export const stepOfRun = run => {
  if (!run) return 0;
  if (run.status === RUN_STATUS.promoted) return 3;
  return 2;
};

// How many of the wizard's steps are done for this request, for the progress line and the tick on each step.
export const doneSteps = ({ classOrderValid, run }) => {
  const done = new Set();
  if (classOrderValid || run) done.add(0);
  if (run) done.add(1);
  if (run && [RUN_STATUS.planReady, RUN_STATUS.promoted].includes(run.status)) done.add(2);
  if (run?.status === RUN_STATUS.promoted) done.add(3);
  return done;
};

// What "Revert last step" does for a request in this status, in words the admin can follow.
export const revertLabel = status => {
  if (status === RUN_STATUS.promoted) return 'Revert promotion';
  if (status === RUN_STATUS.planReady) return 'Discard plan';
  return 'Remove new batch';
};

export const revertMessage = status => {
  if (status === RUN_STATUS.promoted) {
    return 'Revert the promotion? The students are taken out of the new batch again and the plan is kept.';
  }
  if (status === RUN_STATUS.planReady) return 'Discard the plan? You can generate a new one.';
  return 'Remove the new batch? This request is deleted.';
};

// The value of a class's "next class" select: nothing set yet, the final class, or the id of the next class.
export const nextClassValue = mapRow => {
  if (!mapRow) return '';
  return mapRow.toCourseId === null || mapRow.toCourseId === undefined ? FINAL_CLASS : String(mapRow.toCourseId);
};

export const courseMapBody = (fromCourseId, value) => ({
  fromCourseId: Number(fromCourseId),
  toCourseId: value === FINAL_CLASS ? null : Number(value),
});

export const indexCourseMap = map => {
  const byFrom = {};
  (map || []).forEach(row => {
    byFrom[row.fromCourseId] = row;
  });
  return byFrom;
};

// The class order is complete when every class of the batch has a next class (or is marked final).
export const classOrderProgress = (courses, byFrom) => {
  const total = courses?.length || 0;
  const configured = (courses || []).filter(c => byFrom[c.courseId]).length;
  const finalClasses = (courses || []).filter(
    c => byFrom[c.courseId] && nextClassValue(byFrom[c.courseId]) === FINAL_CLASS
  ).length;
  return { total, configured, finalClasses, missing: total - configured };
};

// The classes in the order a student moves through them: each class is followed by its next class, a chain that starts at a class
// nothing leads to. Classes that are not in any chain yet (no order set) keep the order of their ids.
export const sortByClassOrder = (courses, byFrom) => {
  const list = [...(courses || [])].sort((a, b) => a.courseId - b.courseId);
  const byId = new Map(list.map(c => [c.courseId, c]));
  const nextOf = c => {
    const row = byFrom?.[c.courseId];
    return row && row.toCourseId !== null && row.toCourseId !== undefined ? byId.get(row.toCourseId) : undefined;
  };
  const hasIncoming = new Set(
    list
      .map(nextOf)
      .filter(Boolean)
      .map(c => c.courseId)
  );
  const ordered = [];
  const seen = new Set();
  const walk = start => {
    for (let cur = start; cur && !seen.has(cur.courseId); cur = nextOf(cur)) {
      seen.add(cur.courseId);
      ordered.push(cur);
    }
  };
  list.filter(c => !hasIncoming.has(c.courseId)).forEach(walk);
  list.forEach(walk); // whatever a loop in the order left out
  return ordered;
};

// The new batch normally is the next academic year: 2026 - 2027 -> 2027 - 2028 (the name format of the school's batches).
export const suggestNextBatch = batch => {
  const startYear = Number(batch?.startYear);
  const endYear = Number(batch?.endYear);
  if (!startYear || !endYear) return { academicName: '', startYear: '', endYear: '' };
  return { academicName: `${startYear + 1} - ${endYear + 1}`, startYear: startYear + 1, endYear: endYear + 1 };
};

// The rules the backend enforces on a new batch: the end year after the start year, and a start after the source batch's.
export const newBatchFormError = ({ sourceBatchId, sourceStartYear, academicName, startYear, endYear }) => {
  if (!sourceBatchId) return 'Choose the batch to promote from in the Class order step.';
  if (!String(academicName || '').trim()) return 'Enter the name of the new batch.';
  if (!Number(startYear) || !Number(endYear)) return 'Enter the start and end year.';
  if (Number(endYear) <= Number(startYear)) return 'The end year must be after the start year.';
  if (sourceStartYear && Number(startYear) <= Number(sourceStartYear)) {
    return `The new batch must start after the batch you promote from (${sourceStartYear}).`;
  }
  return '';
};

// Only one promotion can be open at a time: a request that is not yet promoted blocks creating another.
export const openRunOf = runs => (runs || []).find(r => [RUN_STATUS.created, RUN_STATUS.planReady].includes(r.status));

// The body to change one student of the plan: only a promoted student has a class to go to.
export const planItemBody = (action, toCourseId) => ({
  action,
  toCourseId: action === 'PROMOTE' && toCourseId !== '' && toCourseId !== null ? Number(toCourseId) : null,
});

export const planCounts = plan => {
  const totals = { promote: 0, graduate: 0, exclude: 0, error: 0 };
  (plan?.summary || []).forEach(row => {
    totals.promote += row.promote || 0;
    totals.graduate += row.graduate || 0;
    totals.exclude += row.exclude || 0;
    totals.error += row.error || 0;
  });
  return totals;
};
