import React from 'react';
import { courseStatic } from 'config/constants';

const text = value => (value === null || value === undefined || value === '' ? '--' : value);
const money = value =>
  value === null || value === undefined || value === '' ? '--' : Number(value).toLocaleString('en-IN');

const student = row => (
  <span>
    {text(row.studentName)} <small style={{ color: '#8b95a1' }}>(#{row.studentId})</small>
  </span>
);

const feeGroup = row => (
  <span>
    {text(row.feeGroupName)}
    {row.feeGroupType && <small style={{ color: '#8b95a1' }}> ({row.feeGroupType})</small>}
  </span>
);

// The preview table of every carry-forward step: what the backend sends for one row, in the columns the admin checks before
// copying. `align: 'right'` is for numbers. Keyed by "<kind>.<step key>".
export const CARRY_COLUMNS = {
  'transport.routes': [
    { label: 'Route id', render: row => text(row.feeStructId) },
    { label: 'Route', render: row => text(row.description) },
    { label: 'Calculation', render: row => text(row.calculationType) },
    { label: 'Areas', align: 'right', render: row => text(row.areaCount) },
  ],
  'transport.students': [
    { label: 'Student', render: student },
    { label: `Previous ${courseStatic.toLowerCase()}`, render: row => text(row.previousCourse) },
    { label: `Current ${courseStatic.toLowerCase()}`, render: row => text(row.currentCourse) },
    { label: 'Area', render: row => text(row.previousAreaName || row.previousAreaId) },
    { label: 'Calculation', render: row => text(row.calc?.name) },
    { label: 'Manual amount', align: 'right', render: row => (row.manualAmount ? money(row.manualAmount) : '--') },
  ],
  'fees.structures': [
    { label: 'Fee group', render: feeGroup },
    { label: 'Fee', render: row => text(row.feeDescription) },
    { label: 'Actual', align: 'right', render: row => money(row.actualAmount) },
    { label: 'Discount', align: 'right', render: row => money(row.discountAmount) },
    { label: 'Discount %', align: 'right', render: row => text(row.discountPercentage) },
    { label: 'Expected', align: 'right', render: row => money(row.expectedAmount) },
  ],
  'fees.courses': [
    { label: courseStatic, render: row => text(row.courseName) },
    { label: 'Fee group', render: row => text(row.feeGroupName) },
    { label: 'Fees', align: 'right', render: row => text(row.feeCount) },
    { label: 'Total expected', align: 'right', render: row => money(row.totalExpectedAmount) },
  ],
  'fees.students': [
    { label: 'Student', render: student },
    { label: `Previous ${courseStatic.toLowerCase()}`, render: row => text(row.previousCourse) },
    { label: `Current ${courseStatic.toLowerCase()}`, render: row => text(row.currentCourse) },
    { label: 'Fee group', render: row => text(row.feeGroupName) },
    { label: 'Fee', render: row => text(row.feeDescription) },
    { label: 'Expected', align: 'right', render: row => money(row.expectedAmount) },
  ],
};

// The one figure a step adds up in its summary line, if any.
export const CARRY_TOTALS = {
  'fees.structures': { field: 'expectedAmount', label: 'Total expected' },
  'fees.courses': { field: 'totalExpectedAmount', label: 'Total expected' },
  'fees.students': { field: 'expectedAmount', label: 'Total expected' },
};
